            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"34\">KNOWLEDGE CHECK</text><rect x=\"150\" y=\"120\" width=\"800\" height=\"180\" rx=\"20\" fill=\"rgba(99,102,241,0.1)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"180\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"22\">FOUR DIETS, ONE YEAR</text><text x=\"550\" y=\"225\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"18\">Atkins -- Zone -- Weight Watchers -- Ornish</text><text x=\"550\" y=\"260\" text-anchor=\"middle\" fill=\"#888\" font-size=\"16\">What separated winners from the rest?</text><rect x=\"250\" y=\"400\" width=\"600\" height=\"160\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"550\" y=\"470\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"26\">Macros?</text><text x=\"550\" y=\"515\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Or something else?</text></svg>",
