            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"34\">WISDOM</text><rect x=\"100\" y=\"160\" width=\"900\" height=\"320\" rx=\"20\" fill=\"rgba(139,92,246,0.1)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/><text x=\"150\" y=\"240\" text-anchor=\"start\" fill=\"#fff\" font-style=\"italic\" font-size=\"22\">\"The best diet is the one you can stick</text><text x=\"150\" y=\"285\" text-anchor=\"start\" fill=\"#fff\" font-style=\"italic\" font-size=\"22\">to -- built from foods you enjoy, in a</text><text x=\"150\" y=\"330\" text-anchor=\"start\" fill=\"#fff\" font-style=\"italic\" font-size=\"22\">pattern that fits your life, for the</text><text x=\"150\" y=\"375\" text-anchor=\"start\" fill=\"#fff\" font-style=\"italic\" font-size=\"22\">long haul.\"</text><text x=\"950\" y=\"440\" text-anchor=\"end\" fill=\"#8b5cf6\" font-size=\"18\">-- Adapted from DIETFITS and Dansinger</text></svg>",
            "caption": "Adherence is the real secret"
