            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"34\">KNOWLEDGE CHECK</text><text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"23\">Why does weight loss level off?</text><line x1=\"150\" y1=\"200\" x2=\"150\" y2=\"620\" stroke=\"#888\" stroke-width=\"2\"/><line x1=\"150\" y1=\"620\" x2=\"950\" y2=\"620\" stroke=\"#888\" stroke-width=\"2\"/><path d=\"M150 220 Q 400 500 600 530 L 950 540\" stroke=\"#8b5cf6\" stroke-width=\"4\" fill=\"none\"/><circle cx=\"700\" cy=\"535\" r=\"14\" fill=\"#ffd700\"/><text x=\"700\" y=\"490\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"20\">Plateau: why?</text><rect x=\"150\" y=\"700\" width=\"800\" height=\"120\" rx=\"20\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"755\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"22\">Drug failure or a new equilibrium?</text><text x=\"550\" y=\"795\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Think back to the set-point lesson</text></svg>",
